package io.github.ningpp.compat;

/** Replacement for System.Text.Json.JsonSerializerOptions (generated by CSharpToJava converter). */
public class JsonSerializerOptions {
    private boolean writeIndented = false;
    private boolean propertyNameCaseInsensitive = false;
    private String propertyNamingPolicy = null;

    public boolean isWriteIndented()                  { return writeIndented; }
    public void    setWriteIndented(boolean v)         { writeIndented = v; }
    public boolean isPropertyNameCaseInsensitive()    { return propertyNameCaseInsensitive; }
    public void    setPropertyNameCaseInsensitive(boolean v) { propertyNameCaseInsensitive = v; }
    public String  getPropertyNamingPolicy()          { return propertyNamingPolicy; }
    public void    setPropertyNamingPolicy(String v)  { propertyNamingPolicy = v; }
}
